  ["924e8ed0"] = "Віднесіть предмет «{item:Eye of the Tempest}» до НІП «{npc:Bath'rah the Windwatcher}» у локації «{zone:Alterac Mountains}».",
  ["ce973e47"] = "Класове завдання шамана з 30-го рівня; відкривається завданням «Call of Air» (завдання з предметом «{item:Air Totem}»). У цьому підземеллі: «{quest:Elemental Aid}». Убийте боса «{npc:Charlga Razorflank}» і заберіть предмет «{item:Tattered Note}»; його отримує кожен шаман із цим завданням. Далі: 20 викривлених тотемів із чотирьох локацій і елітний ритуал «Heed My Call» у локації «{zone:Thousand Needles}».",
  ["d303a745"] = "Це ланцюжок завдань із кроком у підземеллі «{zone:Razorfen Kraul}»",
  ["fa5abda0"] = "Класове завдання шамана з 30-го рівня; відкривається завданням «Call of Air» (завдання з предметом «{item:Air Totem}»). У цьому підземеллі: «{quest:Elemental Aid}». Убийте боса «{npc:Charlga Razorflank}» і заберіть предмет «{item:Tattered Note}»; його отримує кожен шаман із цим завданням. Далі: 20 викривлених тотемів із чотирьох локацій і елітний ритуал «Heed My Call» у локації «{zone:Thousand Needles}». Хто з НІП Орди видає завдання після підземелля, ще не підтверджено («{npc:Prate Cloudseer}» або «{npc:Rau Cliffrunner}»): дивіться журнал завдань.",
  ["dd1d6df1"] = "Зачекайте, поки «{npc:Furen Longbeard}» закінчить вашу броню.",
  ["f23278cc"] = "Класове завдання воїна з 20-го рівня. У цьому підземеллі: для завдання «{quest:Fire Hardened Mail}» потрібен предмет «{item:Vial of Phlogiston}» від «{npc:Roogug}», першого боса. Після завдання «{quest:Fire Hardened Mail}» НІП «{npc:Grimand Elmore}» («{zone:Stormwind}»), «{npc:Klockmort Spannerspan}» («{zone:Ironforge}») і «Mathiel» («{zone:Darnassus}») виготовляють ще по одній частині:",
  ["b58a5bc5"] = "Зачекайте, поки «{npc:Thun'grim Firegaze}» закінчить вашу броню.",
  ["06f50add"] = "Класове завдання воїна з 20-го рівня. У цьому підземеллі: для завдання «{quest:Brutal Armor}» потрібен предмет «{item:Vial of Phlogiston}» від «{npc:Roogug}», першого боса. Після завдання «{quest:Brutal Armor}» НІП «Ula'elek», «{npc:Orm Stonehoof}» («{zone:Thunder Bluff}») і «{npc:Velora Nitely}» виготовляють ще по одній частині:",
  ["11b3361f"] = "Прочитайте предмет «{item:Henrig Lonebrow's Journal}» і віднесіть його до НІП «{npc:Falfindel Waywarder}» у місцевості «{zone:Thalanaar}».",
  ["f93aac54"] = "Потрібне перед завданням «{quest:The Crone of the Kraul}».",
  ["c045f5f4"] = "Увійдіть до печер «{zone:Rethban Caverns}», дійдіть до першої розвилки й вчасно поверніться до НІП «{npc:Yorus Barleybrew}». Не можна загинути й відпустити дух.",
  ["c11c3a7d"] = "Ваш наставник воїнів («{npc:Wu Shen}» у місті «{zone:Stormwind}» або наставники в містах «{zone:Ironforge}» і «{zone:Darnassus}») спершу відправляє вас до НІП «{npc:Yorus Barleybrew}» у місцевості «{zone:Lakeshire}». Проходження обмежене в часі.",
  ["910d2d0d"] = "Зберіть матеріали, потрібні НІП «{npc:Furen Longbeard}», і принесіть їх йому в місто «{zone:Stormwind}».",
  ["6004cf96"] = "Крок у підземеллі «{zone:Razorfen Kraul}».",
  ["e64ab5cc"] = "Принесіть предмет «{item:Cask of Scalder}» до НІП «{npc:Furen Longbeard}».",
  ["6b3687e2"] = "Нагорода від «Furen» — щит «{item:Furen's Favor}».",
  ["4452a134"] = "Принесіть «Twitching Antennae»: 5 шт. до НІП «{npc:Ruga Ragetotem}» у таборі «{zone:Camp Taurajo}».",
  ["4a07884f"] = "Ваш наставник воїнів («Sorek» у місті «{zone:Orgrimmar}») спершу відправляє вас до «Ruga». Ліміт часу: 30 хвилин. Вусики випадають із силітидів на полі «{zone:Field of Giants}», на південь від табору «{zone:Camp Taurajo}».",
  ["fd4f34ea"] = "Поговоріть з НІП «{npc:Thun'grim Firegaze}» у локації «{zone:The Barrens}».",
  ["a8d67620"] = "Принесіть до НІП «{npc:Thun'grim Firegaze}» «{item:Smoky Iron Ingot}»: 15 шт., «{item:Powdered Azurite}»: 10 шт., «{item:Iron Bar}»: 10 шт. і предмет «{item:Vial of Phlogiston}».",
  ["4469b055"] = "Віднесіть предмет «{item:Small Scroll}» до НІП «{npc:Varimathras}» у місті «{zone:Undercity}».",
  ["6c64b9c1"] = "Зберіть «{item:Twisted Fire Totem}»: 5 шт., «{item:Twisted Earth Totem}»: 5 шт., «{item:Twisted Air Totem}»: 5 шт. і «{item:Twisted Water Totem}»: 5 шт. для НІП «{npc:Veyric Thunderhame}» у локації «{zone:Arathi Highlands}».",
  ["f208c4db"] = "Викривлені тотеми випадають, лише поки це завдання є в журналі. Вода: мурлоки з племені Багноплавців, північно-східне узбережжя локації «{zone:Dustwallow Marsh}». Повітря: кентаври з племені Мародінів, «{zone:Desolace}». Земля: Загублені, «{zone:Swamp of Sorrows}». Вогонь: огри з клану Пилоригачів і троги з Кам’яного Сховища, «{zone:Badlands}».",
  ["a2f7c539"] = "Здолайте боса «{npc:Charlga Razorflank}» у підземеллі «{zone:Razorfen Kraul}» і зберіть відомості про плани шипогривів.",
  ["a3ef4bff"] = "Крок у підземеллі «{zone:Razorfen Kraul}». Після завдання «{quest:Call of Air}» НІП «{npc:Prate Cloudseer}» відправляє вас до НІП «{npc:Rau Cliffrunner}». На боці Орди цим завданням не можна поділитися.",
  ["6e0be194"] = "Зберіть «{item:Twisted Fire Totem}»: 5 шт., «{item:Twisted Earth Totem}»: 5 шт., «{item:Twisted Air Totem}»: 5 шт. і «{item:Twisted Water Totem}»: 5 шт. та здайте їх НІП «{npc:Prate Cloudseer}» у локації «{zone:Thousand Needles}».",
  ["9b8d4442"] = "Поговоріть з НІП «{npc:Prate Cloudseer}» у локації «{zone:Thousand Needles}».",
  ["25997477"] = "Використайте викривлені тотеми, щоб зірвати ритуал шипогривів.",
  ["9ba7c810"] = "Елітне, рівень 40: зберіть групу. Біля парових озер у локації «{zone:Thousand Needles}» станьте в коло рун і використайте предмет «{item:Corrupted Totems}». Наступають хвилі елементалів, потім елітний шипогрив і «{npc:Ravaging Tempest}», з якого випадає предмет «{item:Eye of the Tempest}» для кожного шамана із цим завданням. Орда: хто видає завдання, ще не підтверджено; дивіться журнал завдань.",
  ["25262bca"] = "Елітне, рівень 40: зберіть групу. Біля парових озер у локації «{zone:Thousand Needles}» станьте в коло рун і використайте предмет «{item:Corrupted Totems}». Наступають хвилі елементалів, потім елітний шипогрив і «{npc:Ravaging Tempest}», з якого випадає предмет «{item:Eye of the Tempest}» для кожного шамана із цим завданням.",
  ["f4c9f1c3"] = "Крок у підземеллі «{zone:Razorfen Kraul}». «Call of Air» (від НІП «{npc:Eldrun Stormbreaker}» у місті «{zone:Ironforge}») відправляє вас до «Veyric». Шамани Альянсу можуть ділитися цим завданням.",
  ["a96509b8"] = "Віднесіть обручку НІП «{npc:Vorrel Sengutz}» (від НІП «{npc:Nancy Vishas}») до НІП «{npc:Monika Sengutz}» у місцевості «{zone:Tarren Mill}».",
  ["9ca373d8"] = "Принесіть «{item:Heart of Zeal}»: 20 шт. з підземелля «{zone:Scarlet Monastery}» до НІП «{npc:Master Apothecary Faranell}».",
  ["6fd32769"] = "Класове завдання розбійника після завдання «{quest:The Horn of Xelthos}»; наступний лист від «C» (близько 30-го рівня) знову відправляє вас до схованки «Dead Drop». Носіть предмет «{item:Scarlet Initiate's Uniform}» у кожному крилі: непомітність або атака знімають його.",
  ["54a27fc1"] = "Принесіть 1 купку «{item:Kraul Guano}» до НІП «{npc:Master Apothecary Faranell}» у місті «{zone:Undercity}».",
  ["a978de8f"] = "Потрібне перед завданням «{quest:Hearts of Zeal}».",
  ["a6810893"] = "Доступне, коли наступний лист від «C» надійде вам у столиці.",
  ["939fa536"] = "Знайдіть предмет «{item:Eye of Bhossca}» у підземеллі «{zone:Scarlet Monastery}». Потім віднесіть його до схованки «C» біля місцевості «{zone:Pyrewood Village}». Виконати це потрібно самотужки.",
  ["5dccee55"] = "Знайдіть у Монастирі предмет «{item:Mythology of the Titans}» і принесіть його до НІП «{npc:Librarian Mae Paledust}» у місті «{zone:Ironforge}».",
  ["2a190ff1"] = "Здобудьте предмет «{item:The Lost Magic of the Runemasters}» у підземеллі «{zone:Scarlet Monastery}».",
  ["e0d6e812"] = "Нове у Forever. Книга — у боса «{npc:Arcanist Doan}».",
  ["9bbb35d6"] = "Здобудьте в Монастирі предмет «{item:Compendium of the Fallen}» і поверніться до НІП «{npc:Sage Truthseeker}» у місті «{zone:Thunder Bluff}».",
  ["adc91988"] = "Нежить не може взяти це завдання",
  ["1ee768e4"] = "Поговоріть з НІП «{npc:Dorn Plainstalker}» у локації «{zone:Thousand Needles}».",
  ["0b878f84"] = "Це довгий ланцюжок із кроком у крилі «{zone:Library}»",
  ["aeda38f9"] = "Убийте босів «{npc:High Inquisitor Whitemane}», «{npc:Scarlet Commander Mograine}», «{npc:Herod}», «{npc:Scarlet Champion}» і «{npc:Houndmaster Loksey}», а потім поверніться з доповіддю до НІП «{npc:Varimathras}» у місті «{zone:Undercity}».",
  ["84895a94"] = "Бос «{npc:Herod}» — у Зброярні; бос «Локсі» — у крилі «{zone:Library}»; боси «Моґрейн» і «Вайтмейн» — у Соборі.",
  ["20b66310"] = "Поговоріть з НІП «{npc:Brother Anton}» у локації «{zone:Desolace}».",
  ["eaea96a3"] = "Вступний крок до завдання «{quest:In the Name of the Light}».",
  ["a5263287"] = "Убийте босів «{npc:High Inquisitor Whitemane}», «{npc:Scarlet Commander Mograine}», «{npc:Herod}», «{npc:Scarlet Champion}» і «{npc:Houndmaster Loksey}», а потім поверніться з доповіддю до НІП «{npc:Raleigh the Devout}» у місцевості «{zone:Southshore}».",
  ["ae80f690"] = "Бос «{npc:Herod}» — у Зброярні; бос «Локсі» — у крилі «{zone:Library}»; боси «Моґрейн» і «Вайтмейн» — у Соборі.\n\nНеобов’язкове вступне завдання:",
  ["aa3482db"] = "Віднесіть книгу «{item:Rituals of Power}» до НІП «{npc:Tabetha}» у локації «{zone:Dustwallow Marsh}».",
  ["1eedd435"] = "Класове завдання мага.",
  ["64ff75cd"] = "Віднесіть «Brother Anton's Letter of Commendation» до НІП «{npc:Raleigh the Devout}» у місцевості «{zone:Southshore}».",
  ["fe530cd0"] = "Якщо маєте віру, стрибніть із дощок над локацією «{zone:Thousand Needles}».",
  ["1710ebfb"] = "Принесіть предмет «{item:Grenka's Claw}» до НІП «{npc:Dorn Plainstalker}» у локації «{zone:Thousand Needles}».",
  ["324351d4"] = "Принесіть предмет «{item:Fragments of Rok'Alim}» до НІП «{npc:Dorn Plainstalker}» у локації «{zone:Thousand Needles}».",
  ["0057d8b9"] = "Знайдіть НІП «{npc:Braug Dimspirit}» біля входу до «Talondeep Path» у локації «{zone:Stonetalon Mountains}».",
  ["f8a8c2eb"] = "Знайдіть предмет «{item:Legacy of the Aspects}» і віднесіть його до НІП «{npc:Braug Dimspirit}» біля входу до «Talondeep Path» у локації «{zone:Stonetalon Mountains}».",
  ["1b5325b6"] = "Знайдіть НІП «{npc:Parqual Fintallas}» у місті «{zone:Undercity}».",
  ["24fb9e5d"] = "Знайдіть предмет «{item:Beginnings of the Undead Threat}» і віднесіть його до НІП «{npc:Parqual Fintallas}» у місті «{zone:Undercity}».",
  ["08a18f96"] = "Книга — у підземеллі «{zone:Scarlet Monastery}»: крило «{zone:Library}».",
  ["e5d27190"] = "Поговоріть з НІП «{npc:Magus Tirth}» у місцевості «{zone:The Shimmering Flats}».",
  ["7bd8b66f"] = "Дізнайтеся фразу до скрині «Tirth», потім поверніться до «Tirth».",
  ["6a123f4b"] = "Знищте «{npc:Undead Ravager}»: 30, потім поверніться до НІП «{npc:Brother Anton}» у місцевості «{zone:Nijel's Point}».",
  ["124e8c97"] = "Правильно дайте відповідь на запитання НІП «{npc:Braug Dimspirit}», а потім знову поговоріть із ним.",
  ["e1d31203"] = "ВІДПОВІДЬ: Нелтаріон (Neltharion)",
  ["b34b9f52"] = "Правильно дайте відповідь на запитання «Parqual Fintallas», а потім знову поговоріть із ним.",
  ["91250bbe"] = "ВІДПОВІДЬ: Нер’зул (Ner'zhul)",
  ["64d45695"] = "Використайте шкуру й деревне вугілля, щоб зробити відбитки чотирьох «Tablets of I'lalai» у підземеллі «{zone:The Drowned City}».",
  ["5ea9224f"] = "Віднесіть відбитки табличок до НІП «{npc:Master Gadrin}» у поселенні «{zone:Sen'jin Village}» (локація «{zone:Durotar}»).",
  ["30eec9b4"] = "Убийте НІП «Var'Taka» у підземеллі «{zone:The Drowned City}».",
  ["e6af653a"] = "НІП «{npc:Commander Aggro'gosh}» видає його, щойно здано обидва завдання: «Enemies in the Water» і «Locating the Lost City» (від НІП «{npc:Kin'weelay}»).",
  ["f84f688d"] = "Здобудьте предмет «{item:Ancient Gurubashi Idol}» у підземеллі «{zone:The Drowned City}».",
  ["2968e9ba"] = "Зробіть відбитки чотирьох «Tablets of I'lalai» у підземеллі «{zone:The Drowned City}».",
  ["6922d65c"] = "Хто видає завдання, ще не підтверджено. Попереднє завдання: «An Acquaintance» у локації «Southshore» — віднести предмет «{item:Savage Coast Report Bundle}» до НІП «{npc:Loremaster Dibbs}».",
  ["ad1f28b5"] = "Зберіть «{item:I'lalai Fetish}»: 5 шт. з тролів у підземеллі «{zone:The Drowned City}».",
  ["f0622cae"] = "Віднесіть «Dibbs' I'lalai Translations» до НІП «{npc:Historian Karnik}» у місті «{zone:Ironforge}».",
  ["ac2823b0"] = "Віднесіть предмет «{item:I'lalai Fetish}» до НІП «{npc:Abra Cadabra}» у місті «{zone:Dalaran}».",
  ["98276b20"] = "«{npc:Kirin Tor}» пускають до міста «{zone:Dalaran}» лише видатних відвідувачів.",
  ["5a288fe0"] = "Зберіть «{item:Voodoo-Infused Artifact}»: 10 шт. з піратів «Saltseer» у підземеллі «{zone:The Drowned City}».",
  ["152a45b7"] = "Убийте капітана «Dreadrise» і коронерів «Saltseer»: 3 у підземеллі «{zone:The Drowned City}».",
  ["07590325"] = "Убийте «{npc:Kurzen Jungle Fighter}»: 15.",
  ["6aeed6b3"] = "Виконується разом з іншим із двох завдань НІП «{npc:Sergeant Yohwa}» («{quest:The Second Rebellion}» і «{quest:Bad Medicine}»); НІП «{npc:Brother Nimetz}» видає завдання «{quest:Kurzen's Mystery}», щойно здано обидва.",
  ["082f9442"] = "Принесіть «{item:Jungle Remedy}»: 7 шт. і 1 предмет «{item:Venom Fern Extract}» до НІП «{npc:Sergeant Yohwa}».",
  ["99a5d306"] = "Принесіть «{item:Skullsplitter Fetish}»: 4 шт. до НІП «{npc:Brother Nimetz}».",
  ["08b98f76"] = "Знайдіть чотири тролячі таблички на узбережжі й у місцевості «{zone:The Vile Reef}» та принесіть «First», «Second», «Third» і «Fourth Troll Legends».",
  ["1d3f2996"] = "Принесіть предмет «{item:Tablet Shard}» до НІП «{npc:Kin'weelay}» у таборі «{zone:Grom'gol Base Camp}».",
  ["3092b561"] = "Групове завдання: мурлоки «Saltscale» у місцевості «{zone:The Vile Reef}» елітні.",
  ["0dd5359f"] = "Використайте шкуру й деревне вугілля, щоб зробити відбиток таблички «Third Troll Legend».",
  ["ee997802"] = "Розвідайте територію трохи на захід від місцевості «{zone:The Vile Reef}», знайдіть вхід до печери, потім поверніться з доповіддю до НІП «{npc:Kin'weelay}».",
  ["2c03a0b9"] = "Печера — у місцевості «{zone:Sunken Hollow}», під водою близько 21, 28: це вхід до підземелля «{zone:The Drowned City}».",
  ["5aaaa774"] = "Зберіть «{item:Brinescale Trident}»: 10 шт. із застрільників «Brinescale».",
  ["423e6d10"] = "НІП «{npc:Commander Aggro'gosh}» видає його, щойно здано завдання «{quest:The Gurubashi Legends of Old}».",
  ["520d7135"] = "Віднесіть предмет «{item:Savage Coast Report Bundle}» (фетиші, легенди тролів і звіт розвідки) до НІП «{npc:Loremaster Dibbs}» у місцевості «{zone:Southshore}».",
  ["7dc2123a"] = "НІП «{npc:Master Apothecary Faranell}» у місті «{zone:Undercity}» потрібно «{item:Heart of Zeal}»: 20 шт.",
  ["e2a726b8"] = "Збирається по всьому Монастирю: з будь-якого багряного гуманоїда на шляху до Зброярні може випасти «Hearts of Zeal».",
  ["f74b8fe6"] = "Збирається по всьому Монастирю: з будь-якого багряного гуманоїда на шляху до Собору може випасти «Hearts of Zeal».",
}
